:false,"italic":true,"align":"center","lineHeight":1.3},{"id":"i10","type":"image","x":60,"y":726,"w":680,"h":220,"rotation":0,"src":"/tin/trao-quyet-dinh-2.webp","radius":8,"opacity":1,"fit":"cover","borderWidth":4,"borderColor":"#ffd76a"},{"id":"t11","type":"text","x":60,"y":986,"w":680,"rotation":0,"content":"15 BAN CÔNG TÁC MẶT TRẬN  ·  15 TỔ DÂN PHỐ","fontSize":21,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#ffd76a","bold":true,"italic":false,"align":"center","lineHeight":1.3}]'),
  (1, '#fffdf6', '/tin/bg-trang.webp', '[{"id":"t12","type":"text","x":60,"y":96,"w":680,"rotation":0,"content":"TRONG SỐ NÀY","fontSize":44,"fontFamily":"\"Times New Roman\", Times, serif","color":"#a20f1a","bold":true,"italic":false,"align":"center","lineHeight":1.2},{"id":"t13","type":"text","x":60,"y":157,"w":680,"rotation":0,"content":"Bản tin nội bộ của Uỷ ban MTTQ Việt Nam phường Yên Nghĩa","fontSize":20,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#c8a227","bold":false,"italic":true,"align":"center","lineHeight":1.62},{"id":"t14","type":"text","x":60,"y":221,"w":680,"rotation":0,"content":"03    Triển khai nhiều nhiệm vụ trọng tâm, hướng về cơ sở, chăm lo nhân dân","fontSize":24,"fontFamily":"\"Times New Roman\", Times, serif","color":"#0b3f8f","bold":true,"italic":false,"align":"left","lineHeight":1.4},{"id":"t15","type":"text","x":60,"y":304,"w":680,"rotation":0,"content":"07    MTTQ phường lan toả nghĩa tình, tri ân người có công","fontSize":24,"fontFamily":"\"Times New Roman\", Times, serif","color":"#0b3f8f","bold":true,"italic":false,"align":"left","lineHeight":1.4},{"id":"t16","type":"text","x":60,"y":354,"w":680,"rotation":0,"content":"11    Hội Cựu chiến binh dâng hương tưởng niệm các anh hùng liệt sĩ","fontSize":24,"fontFamily":"\"Times New Roman\", Times, serif","color":"#0b3f8f","bold":true,"italic":false,"align":"left","lineHeight":1.4},{"id":"t17","type":"text","x":60,"y":437,"w":680,"rotation":0,"content":"15    Đối thoại, lắng nghe tâm tư của người lao động","fontSize":24,"fontFamily":"\"Times New Roman\", Times, serif","color":"#0b3f8f","bold":true,"italic":false,"align":"left","lineHeight":1.4},{"id":"t18","type":"text","x":60,"y":487,"w":680,"rotation":0,"content":"19    Hoạt động đăng tải trên fanpage phường","fontSize":24,"fontFamily":"\"Times New Roman\", Times, serif","color":"#0b3f8f","bold":true,"italic":false,"align":"left","lineHeight":1.4},{"id":"t19","type":"text","x":60,"y":537,"w":680,"rotation":0,"content":"21    Giấy khen của Ban Chấp hành Đảng bộ phường","fontSize":24,"fontFamily":"\"Times New Roman\", Times, serif","color":"#0b3f8f","bold":true,"italic":false,"align":"left","lineHeight":1.4},{"id":"t20","type":"text","x":60,"y":587,"w":680,"rotation":0,"content":"Nội dung và hình ảnh trong số này được tổng hợp từ các bài viết đã đăng trên Báo Hànộimới về hoạt động của Uỷ ban MTTQ Việt Nam phường Yên Nghĩa.","fontSize":20,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#22303f","bold":false,"italic":true,"align":"left","lineHeight":1.55}]'),
  (2, '#fffdf6', '/tin/bg-trang.webp', '[{"id":"t21","type":"text","x":60,"y":96,"w":680,"rotation":0,"content":"CÔNG TÁC MẶT TRẬN","fontSize":19,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#c8a227","bold":true,"italic":false,"align":"left","lineHeight":1.62},{"id":"t22","type":"text","x":60,"y":133,"w":680,"rotation":0,"content":"Phường Yên Nghĩa: Triển khai nhiều nhiệm vụ trọng tâm, hướng về cơ sở, chăm lo nhân dân","fontSize":33,"fontFamily":"\"Times New Roman\", Times, serif","color":"#a20f1a","bold":true,"italic":false,"align":"left","lineHeight":1.24},{"id":"t23","type":"text","x":60,"y":223,"w":680,"rotation":0,"content":"Trọng Nguyễn · 16/07/2026 - 17:14 · Nguồn: Báo Hànộimới","fontSize":18,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#6b7280","bold":false,"italic":true,"align":"left","lineHeight":1.4},{"id":"i24","type":"image","x":60,"y":262,"w":680,"h":320,"rotation":0,"src":"/tin/bao/sau-thang-1.webp","radius":8,"opacity":1,"fit":"cover","borderWidth":3,"borderColor":"#c8a227"},{"id":"t25","type":"text","x":60,"y":590,"w":680,"rotation":0,"content":"Các đại biểu tham dự hội nghị. Ảnh: VT","fontSize":17,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#6b7280","bold":false,"italic":true,"align":"left","lineHeight":1.4},{"id":"t26","type":"text","x":60,"y":628,"w":680,"rotation":0,"content":"Chiều 16-7, Ủy ban MTTQ Việt Nam phường Yên Nghĩa tổ chức hội nghị đánh giá kết quả công tác Mặt trận 6 tháng đầu năm, triển khai nhiệm vụ trọng tâm 6 tháng cuối năm 2026 và phát động các hoạt động tuyên truyền kỷ niệm 79 năm Ngày Thương binh - Liệt sĩ (27/7/1947-27/7/2026).","fontSize":24,"fontFamily":"\"Times New Roman\", Times, serif","color":"#0b3f8f","bold":true,"italic":false,"align":"left","lineHeight":1.55}]'),
  (3, '#fffdf6', '/tin/bg-trang.webp', '[{"id":"i27","type":"image","x":60,"y":96,"w":328,"h":250,"rotation":0,"src":"/tin/bao/sau-thang-2.webp","radius":8,"opacity":1,"fit":"cover","borderWidth":3,"borderColor":"#c8a227"},{"id":"t28","type":"text","x":60,"y":354,"w":328,"rotation":0,"content":"Phó Bí thư Thường trực Đảng ủy phường Yên Nghĩa Phạm Văn Chiến phát biểu chỉ đạo tại hội nghị. Ảnh: VT","fontSize":17,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#6b7280","bold":false,"italic":true,"align":"left","lineHeight":1.4},{"id":"t29","type":"text","x":412,"y":96,"w":328,"rotation":0,"content":"Báo cáo tại hội nghị cho thấy, trong 6 tháng đầu năm 2026, Ủy ban MTTQ Việt Nam phường và các tổ chức thành viên đã bám sát nhiệm vụ chính trị của địa phương, triển khai hiệu quả các phong trào thi đua yêu nước, cuộc vận động và công tác an sinh xã hội. Hoạt động","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"left","lineHeight":1.62},{"id":"t30","type":"text","x":60,"y":445,"w":680,"rotation":0,"content":"tuyên truyền, vận động nhân dân được đổi mới theo hướng thiết thực, hiệu quả...\n\nMTTQ phường cũng tích cực tham gia công tác giải phóng mặt bằng các dự án trọng điểm, nhất là dự án cải tạo, nâng cấp Quốc lộ 6; đẩy mạnh hoạt động giám sát, phản biện xã hội; phát huy vai trò của ban thanh tra nhân dân, ban giám sát đầu tư của cộng đồng. Các hoạt động chuyển đổi số, xây dựng mô hình “Alo đoàn kết vì Yên Nghĩa hôm nay”, phong trào “Bình dân học vụ số” được duy trì, góp phần nâng cao hiệu quả tương tác giữa chính quyền với người dân.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"left","lineHeight":1.62}]'),
  (4, '#fffdf6', '/tin/bg-trang.webp', '[{"id":"i31","type":"image","x":412,"y":96,"w":328,"h":250,"rotation":0,"src":"/tin/bao/sau-thang-3.webp","radius":8,"opacity":1,"fit":"cover","borderWidth":3,"borderColor":"#c8a227"},{"id":"t32","type":"text","x":412,"y":354,"w":328,"rotation":0,"content":"Quang cảnh hội nghị. Ảnh: VT","fontSize":17,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#6b7280","bold":false,"italic":true,"align":"left","lineHeight":1.4},{"id":"t33","type":"text","x":60,"y":96,"w":328,"rotation":0,"content":"Tại hội nghị, các đại biểu đã tập trung thảo luận, đánh giá kết quả, đề xuất nhiều giải pháp nhằm nâng cao chất lượng hoạt động của Mặt trận ở cơ sở. Các tham luận nhấn mạnh vai trò của ban công tác Mặt trận trong công tác tuyên truyền,","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"left","lineHeight":1.62},{"id":"t34","type":"text","x":60,"y":398,"w":680,"rotation":0,"content":"vận động nhân dân thực hiện chủ trương của Đảng, chính sách, pháp luật của Nhà nước; phát huy sức mạnh khối đại đoàn kết toàn dân; tăng cường ứng dụng công nghệ số trong tuyên truyền, nắm bắt tình hình dư luận tại địa bàn.\n\nPhát biểu chỉ đạo tại hội nghị, Phó Bí thư Thường trực Đảng ủy phường Yên Nghĩa Phạm Văn Chiến biểu dương những kết quả mà Ủy ban MTTQ Việt Nam phường và các tổ chức thành viên đã đạt được trong thời gian qua. Đồng chí đề nghị, thời gian tới, MTTQ phường tiếp tục phát huy vai trò nòng cốt trong xây dựng khối đại đoàn kết toàn dân; nâng cao chất lượng công tác giám sát, phản biện xã hội; chủ động nắm bắt tình hình nhân dân, kịp thời tham mưu giải quyết các vấn đề phát sinh từ cơ sở.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"left","lineHeight":1.62}]'),
  (5, '#fffdf6', '/tin/bg-trang.webp', '[{"id":"i35","type":"image","x":412,"y":96,"w":328,"h":250,"rotation":0,"src":"/tin/bao/sau-thang-4.webp","radius":8,"opacity":1,"fit":"cover","borderWidth":3,"borderColor":"#c8a227"},{"id":"t36","type":"text","x":412,"y":354,"w":328,"rotation":0,"content":"Chủ tịch Ủy ban MTTQ Việt Nam phường Lương Huệ Minh phát biểu tại hội nghị. Ảnh: VT","fontSize":17,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#6b7280","bold":false,"italic":true,"align":"left","lineHeight":1.4},{"id":"t37","type":"text","x":60,"y":96,"w":328,"rotation":0,"content":"Tập trung triển khai hiệu quả các nhiệm vụ trọng tâm của thành phố và địa phương, trong đó có đợt cao điểm chuyển đổi số, các hoạt động hướng tới kỷ niệm 80 năm Ngày Thương binh - Liệt sĩ, công tác tìm kiếm, quy tập, xác định danh tính hài cốt liệt sĩ; phối hợp thực hiện","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"left","lineHeight":1.62},{"id":"t38","type":"text","x":60,"y":445,"w":680,"rotation":0,"content":"tốt công tác giải phóng mặt bằng, góp phần bảo đảm tiến độ các dự án trên địa bàn.\n\nThay mặt Ban Thường trực Ủy ban MTTQ Việt Nam phường, Chủ tịch Ủy ban MTTQ Việt Nam phường Lương Huệ Minh tiếp thu đầy đủ ý kiến chỉ đạo của lãnh đạo Đảng ủy phường và khẳng định sẽ cụ thể hóa các nhiệm vụ thành chương trình, kế hoạch hành động phù hợp với thực tiễn địa phương; tiếp tục đổi mới nội dung, phương thức hoạt động, hướng mạnh về cơ sở, chăm lo tốt hơn đời sống nhân dân, phát huy vai trò của MTTQ trong xây dựng Đảng, chính quyền vững mạnh.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"left","lineHeight":1.62},{"id":"t39","type":"text","x":60,"y":832,"w":680,"rotation":0,"content":"Cũng tại hội nghị, Ủy ban MTTQ Việt Nam phường đã triển khai kế hoạch tuyên truyền và tổ chức các hoạt động kỷ niệm 79 năm Ngày Thương binh - Liệt sĩ.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"left","lineHeight":1.62}]'),
  (6, '#fffdf6', '/tin/bg-trang.webp', '[{"id":"t40","type":"text","x":60,"y":96,"w":680,"rotation":0,"content":"TRI ÂN NGƯỜI CÓ CÔNG","fontSize":19,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#c8a227","bold":true,"italic":false,"align":"left","lineHeight":1.62},{"id":"t41","type":"text","x":60,"y":133,"w":680,"rotation":0,"content":"MTTQ phường Yên Nghĩa lan tỏa nghĩa tình tri ân người có công","fontSize":33,"fontFamily":"\"Times New Roman\", Times, serif","color":"#a20f1a","bold":true,"italic":false,"align":"left","lineHeight":1.24},{"id":"t42","type":"text","x":60,"y":223,"w":680,"rotation":0,"content":"Văn Trọng · 24/07/2026 - 16:27 · Nguồn: Báo Hànộimới","fontSize":18,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#6b7280","bold":false,"italic":true,"align":"left","lineHeight":1.4},{"id":"i43","type":"image","x":60,"y":262,"w":680,"h":320,"rotation":0,"src":"/tin/bao/tri-an-1.webp","radius":8,"opacity":1,"fit":"cover","borderWidth":3,"borderColor":"#c8a227"},{"id":"t44","type":"text","x":60,"y":590,"w":680,"rotation":0,"content":"Đại diện Hội Liên hiệp Phụ nữ phường Yên Nghĩa thăm, tặng quà Mẹ liệt sĩ nhân dịp 27-7. Ảnh: VT","fontSize":17,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#6b7280","bold":false,"italic":true,"align":"left","lineHeight":1.4},{"id":"t45","type":"text","x":60,"y":652,"w":680,"rotation":0,"content":"Nhân kỷ niệm 79 năm Ngày Thương binh - Liệt sĩ (27/7/1947 – 27/7/2026), cùng với các hoạt động thăm hỏi, tặng quà người có công trên địa bàn, Ủy ban MTTQ Việt Nam phường Yên Nghĩa đã phát huy vai trò nòng cốt trong việc tập hợp các tổ chức chính trị - xã hội triển khai nhiều hoạt động tri ân thiết thực, góp phần lan tỏa đạo lý \"Uống nước nhớ nguồn\", \"Đền ơn đáp nghĩa\" trong cộng đồng.","fontSize":24,"fontFamily":"\"Times New Roman\", Times, serif","color":"#0b3f8f","bold":true,"italic":false,"align":"left","lineHeight":1.55}]'),
  (7, '#fffdf6', '/tin/bg-trang.webp', '[{"id":"i46","type":"image","x":60,"y":96,"w":328,"h":250,"rotation":0,"src":"/tin/bao/tri-an-2.webp","radius":8,"opacity":1,"fit":"cover","borderWidth":3,"borderColor":"#c8a227"},{"id":"t47","type":"text","x":60,"y":354,"w":328,"rotation":0,"content":"Hoạt động tri ân của các tổ chức thành viên MTTQ phường Yên Nghĩa góp phần chăm lo đời sống người có công với cách mạng. Ảnh: VT","fontSize":17,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#6b7280","bold":false,"italic":true,"align":"left","lineHeight":1.4},{"id":"t48","type":"text","x":412,"y":96,"w":328,"rotation":0,"content":"Những ngày tháng Bảy, không khí tri ân hiện diện ở nhiều khu dân cư của phường Yên Nghĩa. Các tổ chức thành viên của Mặt trận đã đồng loạt triển khai chương trình thăm hỏi, tặng quà các Mẹ Việt Nam Anh hùng, thương binh, bệnh binh, cựu thanh niên xung phong và gia đình chính sách với sự trân","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"left","lineHeight":1.62},{"id":"t49","type":"text","x":60,"y":469,"w":680,"rotation":0,"content":"trọng, chu đáo.\n\nCác tổ chức thành viên của MTTQ Việt Nam phường Yên Nghĩa đồng loạt triển khai hoạt động tri ân người có công. Hội Liên hiệp Phụ nữ, Đoàn Thanh niên và Hội Cựu chiến binh đã trao nhiều phần quà tới Mẹ Việt Nam Anh hùng, cựu thanh niên xung phong, thương binh và gia đình chính sách, góp phần lan tỏa đạo lý \"Uống nước nhớ nguồn\".","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"left","lineHeight":1.62},{"id":"t50","type":"text","x":60,"y":744,"w":680,"rotation":0,"content":"Các hoạt động được triển khai đồng bộ, phù hợp với điều kiện thực tế của từng tổ chức thành viên, tạo nên sức lan tỏa sâu rộng trong cộng đồng. Qua đó, tiếp tục khẳng định vai trò của MTTQ Việt Nam phường trong việc tập hợp, phát huy sức mạnh khối đại đoàn kết toàn dân, chăm lo đời sống vật chất, tinh thần cho người có công với cách mạng.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"left","lineHeight":1.62}]'),
  (8, '#fffdf6', '/tin/bg-trang.webp', '[{"id":"t51","type":"text","x":60,"y":96,"w":680,"rotation":0,"content":"Chủ tịch Ủy ban MTTQ Việt Nam phường Yên Nghĩa Lương Huệ Minh cho biết, các hoạt động tri ân nhân dịp 27-7 không chỉ là việc làm thường niên mà còn là trách nhiệm, tình cảm và đạo lý của cả hệ thống chính trị đối với những người đã cống hiến, hy sinh vì Tổ quốc.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"left","lineHeight":1.62},{"id":"t52","type":"text","x":60,"y":259,"w":680,"rotation":0,"content":"\"Bằng những phần việc cụ thể, Mặt trận cùng các tổ chức thành viên mong muốn góp phần chăm lo tốt hơn đời sống người có công, đồng thời giáo dục truyền thống yêu nước, lòng biết ơn cho thế hệ trẻ. Chúng tôi xác định công tác ''Đền ơn đáp nghĩa'' phải được thực hiện thường xuyên, liên tục, trở thành nét đẹp trong đời sống cộng đồng và là động lực để củng cố khối đại đoàn kết toàn dân\", bà Lương Huệ Minh chia sẻ.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"left","lineHeight":1.62},{"id":"t53","type":"text","x":60,"y":497,"w":680,"rotation":0,"content":"Theo bà Lương Huệ Minh, bên cạnh việc huy động nguồn lực xã hội hóa để chăm lo người có công, MTTQ phường sẽ tiếp tục phối hợp chặt chẽ với các tổ chức thành viên, các khu dân cư nắm bắt tâm tư, nguyện vọng của các gia đình chính sách, kịp thời đề xuất cấp ủy, chính quyền giải quyết những khó khăn phát sinh, bảo đảm không để người có công nào bị bỏ lại phía sau.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"left","lineHeight":1.62},{"id":"t54","type":"text","x":60,"y":735,"w":680,"rotation":0,"content":"Thông qua chuỗi hoạt động tri ân dịp 27-7, tinh thần \"Uống nước nhớ nguồn\" tiếp tục được lan tỏa sâu rộng trên địa bàn phường Yên Nghĩa. Đây cũng là dịp để mỗi cán bộ, đoàn viên, hội viên và các tầng lớp nhân dân ôn lại truyền thống đấu tranh vẻ vang của dân tộc, bồi đắp lòng yêu nước, ý thức trách nhiệm đối với cộng đồng.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"left","lineHeight":1.62}]'),
  (9, '#fffdf6', '/tin/bg-trang.webp', '[{"id":"t55","type":"text","x":60,"y":96,"w":680,"rotation":0,"content":"Những phần quà tuy giá trị vật chất không lớn nhưng chứa đựng tình cảm, sự biết ơn và trách nhiệm của cả hệ thống chính trị và nhân dân địa phương đối với những người đã hy sinh, cống hiến vì nền độc lập, tự do của Tổ quốc. Qua đó, góp phần xây dựng phường Yên Nghĩa ngày càng đoàn kết, nghĩa tình, phát huy truyền thống cách mạng, chung sức xây dựng quê hương phát triển bền vững.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"left","lineHeight":1.62}]'),
  (10, '#fffdf6', '/tin/bg-trang.webp', '[{"id":"t56","type":"text","x":60,"y":96,"w":680,"rotation":0,"content":"TRI ÂN NGƯỜI CÓ CÔNG","fontSize":19,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#c8a227","bold":true,"italic":false,"align":"left","lineHeight":1.62},{"id":"t57","type":"text","x":60,"y":133,"w":680,"rotation":0,"content":"Hội Cựu chiến binh phường Yên Nghĩa dâng hương tưởng niệm các Anh hùng liệt sĩ","fontSize":33,"fontFamily":"\"Times New Roman\", Times, serif","color":"#a20f1a","bold":true,"italic":false,"align":"left","lineHeight":1.24},{"id":"t58","type":"text","x":60,"y":223,"w":680,"rotation":0,"content":"Văn Trọng · 23/07/2026 - 16:56 · Nguồn: Báo Hànộimới","fontSize":18,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#6b7280","bold":false,"italic":true,"align":"left","lineHeight":1.4},{"id":"i59","type":"image","x":60,"y":262,"w":680,"h":320,"rotation":0,"src":"/tin/bao/ccb-1.webp","radius":8,"opacity":1,"fit":"cover","borderWidth":3,"borderColor":"#c8a227"},{"id":"t60","type":"text","x":60,"y":590,"w":680,"rotation":0,"content":"Hội Cựu chiến binh phường Yên Nghĩa tổ chức lễ dâng hương, dâng hoa tưởng niệm các Anh hùng liệt sĩ. Ảnh: VT","fontSize":17,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#6b7280","bold":false,"italic":true,"align":"left","lineHeight":1.4},{"id":"t61","type":"text","x":60,"y":652,"w":680,"rotation":0,"content":"Nhân kỷ niệm 79 năm Ngày Thương binh - Liệt sĩ (27-7-1947 – 27-7-2026), chiều 23-7, Hội Cựu chiến binh phường Yên Nghĩa đã tổ chức lễ dâng hương, dâng hoa tưởng niệm các Anh hùng liệt sĩ tại Tượng đài Chiến thắng và các Đài tưởng niệm Nghĩa trang Liệt sĩ trên địa bàn phường, đồng thời gặp mặt, tri ân đại diện Hợp tác xã Thương binh 27-7 và triển khai nhiệm vụ trọng tâm công tác Hội thời gian tới.","fontSize":24,"fontFamily":"\"Times New Roman\", Times, serif","color":"#0b3f8f","bold":true,"italic":false,"align":"left","lineHeight":1.55}]'),
  (11, '#fffdf6', '/tin/bg-trang.webp', '[{"id":"i62","type":"image","x":60,"y":96,"w":328,"h":250,"rotation":0,"src":"/tin/bao/ccb-2.webp","radius":8,"opacity":1,"fit":"cover","borderWidth":3,"borderColor":"#c8a227"},{"id":"t63","type":"text","x":60,"y":354,"w":328,"rotation":0,"content":"Những người lính năm xưa thành kính thắp nén hương tri ân đồng đội đã ngã xuống vì sự nghiệp bảo vệ Tổ quốc. Ảnh: VT","fontSize":17,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#6b7280","bold":false,"italic":true,"align":"left","lineHeight":1.4},{"id":"t64","type":"text","x":412,"y":96,"w":328,"rotation":0,"content":"Dự chương trình có đại diện Hội Cựu chiến binh thành phố; lãnh đạo Đảng ủy, HĐND, UBND, Ủy ban MTTQ Việt Nam phường Yên Nghĩa cùng đông đảo cán bộ, hội viên Hội Cựu chiến binh và các đại biểu khách","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"left","lineHeight":1.62},{"id":"t65","type":"text","x":60,"y":445,"w":680,"rotation":0,"content":"mời.\n\nTrong không khí trang nghiêm, các đại biểu thành kính dâng hương, dâng hoa, dành phút mặc niệm tưởng nhớ Chủ tịch Hồ Chí Minh, các Anh hùng liệt sĩ, các Mẹ Việt Nam Anh hùng và những người con ưu tú của dân tộc đã anh dũng chiến đấu, hy sinh vì độc lập, tự do của Tổ quốc. Những nén hương thơm thể hiện lòng biết ơn sâu sắc, đồng thời nhắc nhở các thế hệ hôm nay tiếp tục phát huy truyền thống cách mạng, chung sức xây dựng quê hương ngày càng giàu đẹp, văn minh.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"left","lineHeight":1.62}]'),
  (12, '#fffdf6', '/tin/bg-trang.webp', '[{"id":"i66","type":"image","x":412,"y":96,"w":328,"h":250,"rotation":0,"src":"/tin/bao/ccb-3.webp","radius":8,"opacity":1,"fit":"cover","borderWidth":3,"borderColor":"#c8a227"},{"id":"t67","type":"text","x":412,"y":354,"w":328,"rotation":0,"content":"Chủ tịch Hội Cựu chiến binh phường Yên Nghĩa Đoàn Viết Mạnh dâng hương tưởng niệm các Anh hùng liệt sĩ tại Nghĩa trang Liệt sĩ phường. Ảnh: VT","fontSize":17,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#6b7280","bold":false,"italic":true,"align":"left","lineHeight":1.4},{"id":"t68","type":"text","x":60,"y":96,"w":328,"rotation":0,"content":"Ông Lê Ngọc Ninh, cựu chiến binh từng chiến đấu tại mặt trận Vị Xuyên, không giấu được xúc động: \" Có những đồng đội mãi mãi dừng lại ở tuổi đôi mươi. Mỗi lần thắp nén hương tri ân, tôi như thấy họ vẫn đang ở bên mình. Đây không chỉ là hoạt động tưởng nhớ những người đã ngã xuống mà còn là dịp","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"left","lineHeight":1.62},{"id":"t69","type":"text","x":60,"y":469,"w":680,"rotation":0,"content":"để những cựu chiến binh như chúng tôi nhắc nhau tiếp tục phát huy phẩm chất Bộ đội Cụ Hồ, giáo dục con cháu về truyền thống yêu nước\".\n\nChủ tịch Hội Cựu chiến binh phường Yên Nghĩa Đoàn Viết Mạnh cho biết, hoạt động dâng hương và tri ân là dịp để cán bộ, hội viên bày tỏ lòng biết ơn đối với sự hy sinh to lớn của các thế hệ cha anh, đồng thời giáo dục truyền thống yêu nước, đạo lý \"Uống nước nhớ nguồn\" cho thế hệ trẻ.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"left","lineHeight":1.62}]'),
  (13, '#fffdf6', '/tin/bg-trang.webp', '[{"id":"t70","type":"text","x":60,"y":96,"w":680,"rotation":0,"content":"Theo ông Đoàn Viết Mạnh, thời gian tới, Hội sẽ tiếp tục phát huy vai trò nòng cốt của hội viên trong tuyên truyền, vận động nhân dân thực hiện tốt các chủ trương của Đảng, chính sách, pháp luật của Nhà nước; tích cực tham gia xây dựng đô thị văn minh, giữ gìn an ninh trật tự, bảo vệ môi trường và các phong trào thi đua tại địa phương.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"left","lineHeight":1.62},{"id":"t71","type":"text","x":60,"y":296,"w":680,"rotation":0,"content":"Cùng ngày, Hội Cựu chiến binh phường tổ chức hội nghị Ban Chấp hành mở rộng kết hợp gặp mặt, tri ân đại diện Hợp tác xã Thương binh 27-7. Tại chương trình, Hội đã trao những phần quà ý nghĩa, động viên các thương binh tiếp tục phát huy phẩm chất Bộ đội Cụ Hồ, gương mẫu trong các phong trào thi đua yêu nước, tích cực tham gia xây dựng hệ thống chính trị ở cơ sở và phát triển kinh tế - xã hội địa phương.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"left","lineHeight":1.62}]'),
  (14, '#fffdf6', '/tin/bg-trang.webp', '[{"id":"t72","type":"text","x":60,"y":96,"w":680,"rotation":0,"content":"ĐOÀN THỂ","fontSize":19,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#c8a227","bold":true,"italic":false,"align":"left","lineHeight":1.62},{"id":"t73","type":"text","x":60,"y":133,"w":680,"rotation":0,"content":"Yên Nghĩa đối thoại, lắng nghe tâm tư của người lao động","fontSize":33,"fontFamily":"\"Times New Roman\", Times, serif","color":"#a20f1a","bold":true,"italic":false,"align":"left","lineHeight":1.24},{"id":"t74","type":"text","x":60,"y":223,"w":680,"rotation":0,"content":"Nguyễn Trọng · 31/07/2026 - 16:25 · Nguồn: Báo Hànộimới","fontSize":18,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#6b7280","bold":false,"italic":true,"align":"left","lineHeight":1.4},{"id":"i75","type":"image","x":60,"y":262,"w":680,"h":320,"rotation":0,"src":"/tin/bao/cong-doan-1.webp","radius":8,"opacity":1,"fit":"cover","borderWidth":3,"borderColor":"#c8a227"},{"id":"t76","type":"text","x":60,"y":590,"w":680,"rotation":0,"content":"Phó Bí thư Đảng ủy, Chủ tịch UBND phường Yên Nghĩa Lê Xuân Hoàn phát biểu tại Hội nghị gặp gỡ, tiếp xúc, đối thoại với đoàn viên, người lao động năm 2026. Ảnh:YN","fontSize":17,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#6b7280","bold":false,"italic":true,"align":"left","lineHeight":1.4},{"id":"t77","type":"text","x":60,"y":652,"w":680,"rotation":0,"content":"Sáng 31-7, Đảng ủy - HĐND - UBND - Ủy ban MTTQ Việt Nam phường Yên Nghĩa phối hợp với Công đoàn phường tổ chức Hội nghị gặp gỡ, tiếp xúc, đối thoại với đoàn viên, người lao động trên địa bàn năm 2026. Đây là diễn đàn để người đứng đầu cấp ủy, chính quyền trực tiếp lắng nghe tâm tư, nguyện vọng, kịp thời tháo gỡ những khó khăn, vướng mắc, góp phần phát huy dân chủ ở cơ sở và xây dựng quan hệ lao động hài hòa.","fontSize":24,"fontFamily":"\"Times New Roman\", Times, serif","color":"#0b3f8f","bold":true,"italic":false,"align":"left","lineHeight":1.55}]'),
  (15, '#fffdf6', '/tin/bg-trang.webp', '[{"id":"i78","type":"image","x":60,"y":96,"w":328,"h":250,"rotation":0,"src":"/tin/bao/cong-doan-2.webp","radius":8,"opacity":1,"fit":"cover","borderWidth":3,"borderColor":"#c8a227"},{"id":"t79","type":"text","x":60,"y":354,"w":328,"rotation":0,"content":"Hội nghị gặp gỡ, tiếp xúc, đối thoại giữa người đứng đầu cấp ủy, chính quyền với đoàn viên, người lao động trên địa bàn phường Yên Nghĩa. Ảnh:YN","fontSize":17,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#6b7280","bold":false,"italic":true,"align":"left","lineHeight":1.4},{"id":"t80","type":"text","x":412,"y":96,"w":328,"rotation":0,"content":"Phó Bí thư Đảng ủy, Chủ tịch UBND phường Yên Nghĩa Lê Xuân Hoàn cho biết, hiện trên địa bàn có gần 1.500 đoàn viên, người lao động thuộc các công đoàn cơ sở khối trường học và doanh nghiệp. Đây là lực lượng quan trọng, đóng góp tích cực vào phát triển kinh tế - xã hội, bảo đảm quốc","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"left","lineHeight":1.62},{"id":"t81","type":"text","x":60,"y":469,"w":680,"rotation":0,"content":"phòng, an ninh của địa phương.\n\nTuy nhiên, đời sống của một bộ phận người lao động vẫn còn khó khăn; việc làm, thu nhập ở một số lĩnh vực chưa ổn định, trong khi các vấn đề về nhà ở, an sinh xã hội, trường học cho con em, thiết chế văn hóa, thể thao vẫn cần tiếp tục được quan tâm.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"left","lineHeight":1.62}]'),
  (16, '#fffdf6', '/tin/bg-trang.webp', '[{"id":"i82","type":"image","x":412,"y":96,"w":328,"h":250,"rotation":0,"src":"/tin/bao/cong-doan-3.webp","radius":8,"opacity":1,"fit":"cover","borderWidth":3,"borderColor":"#c8a227"},{"id":"t83","type":"text","x":412,"y":354,"w":328,"rotation":0,"content":"Nhiều ý kiến, kiến nghị của đoàn viên, người lao động được lãnh đạo địa phương trao đổi, làm rõ ngay tại hội nghị. Ảnh: YN","fontSize":17,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#6b7280","bold":false,"italic":true,"align":"left","lineHeight":1.4},{"id":"t84","type":"text","x":60,"y":96,"w":328,"rotation":0,"content":"Với tinh thần dân chủ, thẳng thắn và trách nhiệm, lãnh đạo phường đề nghị đoàn viên, người lao động tập trung trao đổi những nội dung liên quan đến việc làm, tiền lương, điều kiện lao động, chế độ bảo hiểm xã hội, bảo hiểm y tế, bảo hiểm thất nghiệp; đồng thời phản","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"left","lineHeight":1.62},{"id":"t85","type":"text","x":60,"y":445,"w":680,"rotation":0,"content":"ánh những vấn đề về nhà ở xã hội, vệ sinh môi trường, an ninh trật tự, an toàn giao thông và hoạt động của tổ chức công đoàn.\n\nCác ý kiến, kiến nghị tại hội nghị được lãnh đạo UBND phường và các đơn vị liên quan trực tiếp trao đổi, giải đáp. Đối với những nội dung thuộc thẩm quyền, UBND phường giao các bộ phận chuyên môn tiếp thu, tham mưu giải quyết kịp thời; những vấn đề vượt thẩm quyền sẽ được tổng hợp, báo cáo cấp có thẩm quyền xem xét, xử lý theo quy định. Sau hội nghị, Công đoàn phường phối hợp với các đơn vị liên quan theo dõi, đôn đốc việc giải quyết, bảo đảm các kiến nghị chính đáng của đoàn viên, người lao động được trả lời đầy đủ.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"left","lineHeight":1.62}]'),
  (17, '#fffdf6', '/tin/bg-trang.webp', '[{"id":"t86","type":"text","x":60,"y":96,"w":680,"rotation":0,"content":"Nhân dịp này, Ban Tổ chức đã trao quà cho đoàn viên, người lao động có hoàn cảnh khó khăn. Hoạt động không chỉ thể hiện sự quan tâm của cấp ủy, chính quyền và tổ chức công đoàn đối với người lao động mà còn góp phần củng cố niềm tin, tăng cường sự gắn kết giữa chính quyền với đoàn viên, người lao động, hướng tới xây dựng chính quyền phục vụ, gần dân và vì dân.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"left","lineHeight":1.62}]'),
  (18, '#fffdf6', '/tin/bg-trang.webp', '[{"id":"t87","type":"text","x":60,"y":96,"w":680,"rotation":0,"content":"TIN TRÊN FANPAGE PHƯỜNG","fontSize":19,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#c8a227","bold":true,"italic":false,"align":"left","lineHeight":1.62},{"id":"t88","type":"text","x":60,"y":133,"w":680,"rotation":0,"content":"HOẠT ĐỘNG ĐƯỢC ĐĂNG TẢI TRÊN TRANG CỘNG ĐỒNG","fontSize":30,"fontFamily":"\"Times New Roman\", Times, serif","color":"#a20f1a","bold":true,"italic":false,"align":"left","lineHeight":1.24},{"id":"t89","type":"text","x":60,"y":223,"w":680,"rotation":0,"content":"Ba hoạt động dưới đây được đăng trên fanpage của phường. Facebook không cho phép tải nội dung tự động, nên bản tin chỉ dẫn lại tiêu đề; hình ảnh và bài viết đầy đủ xin xem trên fanpage.","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#6b7280","bold":false,"italic":true,"align":"left","lineHeight":1.55},{"id":"t90","type":"text","x":60,"y":345,"w":680,"rotation":0,"content":"1. Tuyên truyền công tác giải phóng mặt bằng","fontSize":25,"fontFamily":"\"Times New Roman\", Times, serif","color":"#0b3f8f","bold":true,"italic":false,"align":"left","lineHeight":1.35},{"id":"t91","type":"text","x":60,"y":385,"w":680,"rotation":0,"content":"Bài viết và hình ảnh đăng trên fanpage phường Yên Nghĩa.","fontSize":21,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"left","lineHeight":1.5},{"id":"t92","type":"text","x":60,"y":421,"w":680,"rotation":0,"content":"Xem trên fanpage →","fontSize":19,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#a20f1a","bold":false,"italic":true,"align":"left","lineHeight":1.62,"href":"https://www.facebook.com/share/p/14qF1b89ttH/"},{"id":"t93","type":"text","x":60,"y":472,"w":680,"rotation":0,"content":"2. MTTQ thăm hỏi, tặng quà tổ công tác tham gia tuyên truyền giải phóng mặt bằng","fontSize":25,"fontFamily":"\"Times New Roman\", Times, serif","color":"#0b3f8f","bold":true,"italic":false,"align":"left","lineHeight":1.35},{"id":"t94","type":"text","x":60,"y":546,"w":680,"rotation":0,"content":"Bài viết và hình ảnh đăng trên fanpage phường Yên Nghĩa.","fontSize":21,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"left","lineHeight":1.5},{"id":"t95","type":"text","x":60,"y":582,"w":680,"rotation":0,"content":"Xem trên fanpage →","fontSize":19,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#a20f1a","bold":false,"italic":true,"align":"left","lineHeight":1.62,"href":"https://www.facebook.com/share/p/1EgRTBx2Ru/?mibextid=wwXIfr"},{"id":"t96","type":"text","x":60,"y":633,"w":680,"rotation":0,"content":"3. Hội Liên hiệp Phụ nữ phường viếng nghĩa trang liệt sĩ","fontSize":25,"fontFamily":"\"Times New Roman\", Times, serif","color":"#0b3f8f","bold":true,"italic":false,"align":"left","lineHeight":1.35},{"id":"t97","type":"text","x":60,"y":673,"w":680,"rotation":0,"content":"Bài viết và hình ảnh đăng trên fanpage phường Yên Nghĩa.","fontSize":21,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"left","lineHeight":1.5},{"id":"t98","type":"text","x":60,"y":709,"w":680,"rotation":0,"content":"Xem trên fanpage →","fontSize":19,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#a20f1a","bold":false,"italic":true,"align":"left","lineHeight":1.62,"href":"https://www.facebook.com/share/p/1FRNSXhiPg/?mibextid=wwXIfr"}]'),
  (19, '#fffdf6', '/tin/bg-trang.webp', '[{"id":"i99","type":"image","x":60,"y":96,"w":680,"h":250,"rotation":0,"src":"/tin/trao-quyet-dinh-2.webp","radius":8,"opacity":1,"fit":"cover","borderWidth":3,"borderColor":"#c8a227"},{"id":"t100","type":"text","x":60,"y":354,"w":680,"rotation":0,"content":"Ảnh tư liệu hoạt động của Mặt trận phường Yên Nghĩa.","fontSize":18,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#6b7280","bold":false,"italic":true,"align":"left","lineHeight":1.4}]'),
  (20, '#fffdf6', '/tin/bg-trang.webp', '[{"id":"t101","type":"text","x":60,"y":96,"w":680,"rotation":0,"content":"GHI NHẬN","fontSize":19,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#c8a227","bold":true,"italic":false,"align":"left","lineHeight":1.62},{"id":"t102","type":"text","x":60,"y":133,"w":680,"rotation":0,"content":"GIẤY KHEN CỦA BAN CHẤP HÀNH ĐẢNG BỘ PHƯỜNG","fontSize":31,"fontFamily":"\"Times New Roman\", Times, serif","color":"#a20f1a","bold":true,"italic":false,"align":"left","lineHeight":1.24},{"id":"i103","type":"image","x":60,"y":226,"w":680,"h":470,"rotation":0,"src":"/tin/giay-khen.webp","radius":8,"opacity":1,"fit":"cover","borderWidth":4,"borderColor":"#e6d9a8"},{"id":"t104","type":"text","x":60,"y":710,"w":680,"rotation":0,"content":"Ban Chấp hành Đảng bộ phường Yên Nghĩa tặng Giấy khen cho Cơ quan Uỷ ban MTTQ phường vì đã có thành tích xuất sắc trong 1 năm thực hiện chính quyền địa phương 2 cấp.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"left","lineHeight":1.6},{"id":"t105","type":"text","x":60,"y":828,"w":680,"rotation":0,"content":"Số 212 — QĐ/ĐU, ngày 22 tháng 7 năm 2026.","fontSize":20,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#c8a227","bold":false,"italic":true,"align":"left","lineHeight":1.4}]'),
  (21, '#0b3f8f', '/tin/bg-bia-sau.webp', '[{"id":"i106","type":"image","x":345,"y":330,"w":110,"h":110,"rotation":0,"src":"/brand/emblem.webp","radius":0,"opacity":1,"fit":"contain","borderWidth":0,"borderColor":"#c8a227"},{"id":"t107","type":"text","x":60,"y":470,"w":680,"rotation":0,"content":"UỶ BAN MẶT TRẬN TỔ QUỐC VIỆT NAM\nPHƯỜNG YÊN NGHĨA","fontSize":33,"fontFamily":"\"Times New Roman\", Times, serif","color":"#ffffff","bold":true,"italic":false,"align":"center","lineHeight":1.35},{"id":"t108","type":"text","x":60,"y":606,"w":680,"rotation":0,"content":"BẢN TIN MẶT TRẬN  ·  SỐ 01  ·  THÁNG 7/2026","fontSize":24,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#ffd76a","bold":true,"italic":false,"align":"center","lineHeight":1.4},{"id":"t109","type":"text","x":60,"y":656,"w":680,"rotation":0,"content":"15 Ban Công tác Mặt trận tại 15 Tổ dân phố trực thuộc","fontSize":22,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#cfe0ff","bold":false,"italic":false,"align":"center","lineHeight":1.5}]')
